INSERT INTO result(order_id, net_amount) SELECT new_order_id, new_amount FROM batch_changes WHERE tbl = 'orders' AND op = 'insert';
UPDATE result SET net_amount = net_amount + b.delta FROM (SELECT old_order_id AS oid, new_amount - old_amount AS delta FROM batch_changes WHERE tbl = 'orders' AND op = 'update') AS b WHERE result.order_id = b.oid;
DELETE FROM result WHERE order_id IN (SELECT old_order_id FROM batch_changes WHERE tbl = 'orders' AND op = 'delete');
UPDATE result SET net_amount = result.net_amount - b.amt FROM (SELECT new_refund_order_id AS oid, SUM(new_refund_amount) AS amt FROM batch_changes WHERE tbl = 'refunds' AND op = 'insert' GROUP BY new_refund_order_id) AS b WHERE result.order_id = b.oid;
